body {
    background-color: var(--bg-color);
    color: var(--on-background);
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    margin: 0;
    display: flex;
    justify-content: center;
    align-items: flex-start;
    min-height: 100vh;
    padding: 2rem;
}

main {
    background-color: var(--surface-color);
    padding: 2.5rem;
    border-radius: 8px;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
    max-width: 600px;
    width: 100%;
}

h1 {
    color: var(--primary-color);
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 2rem;
    text-align: center;
}

.form-field {
    margin-bottom: 2rem;
    border: none;
    padding: 0;
}

fieldset {
    border: none;
    padding: 0;
    margin: 0;
}

legend {
    font-size: 1.25rem;
    font-weight: 600;
    margin-bottom: 0.5rem;
    color: var(--on-surface);
}

.help-text {
    font-size: 0.9rem;
    color: #aaaaaa;
    margin-bottom: 1rem;
    display: block;
}

.options-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.checkbox-container {
    display: flex;
    align-items: center;
    cursor: pointer;
    font-size: 1rem;
    padding: 0.5rem;
    border-radius: 4px;
    transition: background-color 0.2s;
}

.checkbox-container:hover {
    background-color: rgba(255, 255, 255, 0.05);
}

input[type="checkbox"] {
    appearance: none;
    -webkit-appearance: none;
    width: 20px;
    height: 20px;
    border: 2px solid var(--primary-color);
    border-radius: 4px;
    margin-right: 12px;
    position: relative;
    cursor: pointer;
    background-color: transparent;
    flex-shrink: 0;
}

input[type="checkbox"]:checked {
    background-color: var(--primary-color);
}

input[type="checkbox"]:checked::after {
    content: '✔';
    position: absolute;
    color: var(--bg-color);
    font-size: 14px;
    left: 3px;
    top: -1px;
}

input[type="checkbox"]:focus-visible {
    outline: var(--focus-outline);
    outline-offset: 2px;
}

.submit-btn {
    background-color: var(--primary-color);
    color: var(--bg-color);
    border: none;
    padding: 0.75rem 1.5rem;
    font-size: 1.1rem;
    font-weight: bold;
    border-radius: 4px;
    cursor: pointer;
    width: 100%;
    transition: opacity 0.2s, transform 0.1s;
}

.submit-btn:hover {
    opacity: 0.9;
}

.submit-btn:active {
    transform: scale(0.98);
}

.submit-btn:focus-visible {
    outline: var(--focus-outline);
    outline-offset: 4px;
}

.result {
    margin-top: 1.5rem;
    padding: 1rem;
    border-radius: 4px;
    background-color: rgba(187, 134, 252, 0.1);
    border: 1px solid var(--primary-color);
    text-align: center;
}
