const QuizQuestion = ({ id, question, helpText, options, selectedOptions, onChange, required }) => {
    const helpId = helpText ? `${id}-help` : null;

    return (
        <div className="form-field">
            <fieldset aria-describedby={helpId}>
                <legend>
                    {question}
                    {required && <span aria-hidden="true" style={{color: 'var(--error-color)', marginLeft: '4px'}}>*</span>}
                    {required && <span className="sr-only"> (required)</span>}
                </legend>
                {helpText && (
                    <span id={helpId} className="help-text">
                        {helpText}
                    </span>
                )}
                <div className="options-group">
                    {options.map((option, index) => (
                        <label key={index} className="checkbox-container">
                            <input
                                type="checkbox"
                                value={option}
                                checked={selectedOptions.includes(option)}
                                onChange={() => onChange(option)}
                            />
                            {option}
                        </label>
                    ))}
                </div>
            </fieldset>
        </div>
    );
};

const Quiz = () => {
    const questions = [
        {
            id: 'q1',
            question: "Which of these languages are statically typed?",
            helpText: "Statically typed languages perform type checking at compile-time.",
            options: ["C++", "Java", "Python", "Ruby"]
        },
        {
            id: 'q2',
            question: "Which of these are commonly used for web development?",
            options: ["JavaScript", "CSS", "Swift", "SQL"]
        },
        {
            id: 'q3',
            question: "Which of these languages support functional programming paradigms?",
            options: ["Haskell", "Scala", "Lisp", "COBOL"]
        }
    ];

    const [answers, setAnswers] = useState({
        q1: [],
        q2: [],
        q3: []
    });

    const [submitted, setSubmitted] = useState(false);

    const handleCheckboxChange = (questionId, option) => {
        setAnswers(prev => {
            const currentAnswers = prev[questionId];
            if (currentAnswers.includes(option)) {
                return { ...prev, [questionId]: currentAnswers.filter(a => a !== option) };
            } else {
                return { ...prev, [questionId]: [...currentAnswers, option] };
            }
        });
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        setSubmitted(true);
        console.log("Submitted answers:", answers);
    };

    return (
        <main id="main-content">
            <h1>Computer Languages Quiz</h1>
            <form onSubmit={handleSubmit}>
                {questions.map((q) => (
                    <QuizQuestion
                        key={q.id}
                        id={q.id}
                        question={q.question}
                        helpText={q.helpText}
                        options={q.options}
                        selectedOptions={answers[q.id]}
                        onChange={(option) => handleCheckboxChange(q.id, option)}
                    />
                ))}
                <button type="submit" className="submit-btn">Submit Quiz</button>
            </form>
            {submitted && (
                <div className="result" aria-live="polite">
                    Thank you for completing the quiz! Check the console for your results.
                </div>
            )}
        </main>
    );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<Quiz />);
